class IntentIcebergParams(BaseModel):
    numberOfLegs: Optional[int] = None
    maxQtyPerLeg: Optional[int] = None

    @model_validator(mode="after")
    def check_exclusive(self):
        if self.numberOfLegs is not None and self.maxQtyPerLeg is not None:
            raise ValueError("numberOfLegs and maxQtyPerLeg are mutually exclusive")
        return self


