# ─────────────────────────────────────────────
# MAIN ORDER STRUCT
# ─────────────────────────────────────────────

class IntentOrderStruct(BaseModel):

    orderId: Optional[int] = None
    refId: Optional[int] = None
    qty: int
    side: Optional[IntentOrderSide] = None
    deliveryType: IntentDeliveryType
    priceType: Optional[IntentPriceType] = None
    validityType: Optional[IntentValidityType] = None
    goodTillDate: Optional[str] = None
    executionMode: Optional[str] = None
    entryPrice: Optional[int] = None
    icebergInfo: Optional[IntentIcebergParams] = None
    legs: Optional[List[IntentLeg]] = Field(default_factory=list)
    entryConfig: Optional[IntentEntryConfig] = None
    exitConfig: Optional[IntentExitConfig] = None
    algoId: Optional[str] = None
    stratTags: Optional[List[str]] = Field(default_factory=list)
    echoFields: Optional[str] = None
    isMultiLeg: Optional[bool] = False

    @model_validator(mode="after")
    def validate_fields(self):
        if self.isMultiLeg:
            if self.refId is not None:
                raise ValueError("refId must be absent for multi-leg orders")
            if not self.legs:
                raise ValueError("legs must be non-empty for multi-leg orders")
            if self.side and self.side == IntentOrderSide.SELL:
                raise ValueError("can not sell multi-leg orders")
        else:
            if self.side is None:
                raise ValueError("side is required for single-leg orders")
        return self


